"""Writes voice-processor-fixture.json from lxsrs_v2's audio.py VoiceProcessor (the transmit gain and limiter), so the
renderer port (app/public/js/radio/voice-processor.js) is checked against what the Python did. Run once by hand, from
crc-desktop/, with numpy installed:

    python3 -I tests/fixtures/srs/make-voice-processor-fixture.py
"""
import json
import math
import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent
sys.path.insert(0, str(HERE.parents[2] / "python-pkg"))

import numpy as np  # noqa: E402
from lxsrs_v2.audio import VoiceProcessor  # noqa: E402

N = 960
blocks_in = []
for k, amp in enumerate([0.2, 0.9, 1.6, 0.5, 0.3, 0.3, 0.1]):
    blocks_in.append([amp * math.sin(2 * math.pi * 440 * (k * N + i) / 48000) for i in range(N)])

vp = VoiceProcessor(volume=1.5, block_duration_ms=20)
blocks_out = []
for b in blocks_in:
    pcm = vp.process(np.array(b, dtype=np.float32))
    blocks_out.append((np.frombuffer(pcm, dtype=np.int16).astype(np.int32)).tolist())

(HERE / "voice-processor-fixture.json").write_text(json.dumps({
    "_comment": "Generated by make-voice-processor-fixture.py from lxsrs_v2 audio.py VoiceProcessor. s16 output.",
    "volume": 1.5, "blockMs": 20, "in": blocks_in, "outS16": blocks_out}) + "\n")
print("wrote", HERE / "voice-processor-fixture.json")
